#include <stdio.h>
typedef struct Axis6W5ReplayRow { unsigned int lane, checkpoint, shadow, token; int delta; } Axis6W5ReplayRow;
typedef struct Axis6W5ReplayAgg { unsigned int checkpoint[4], shadow[4], seen_mask[4]; int value[4]; } Axis6W5ReplayAgg;
static unsigned int mix5r(unsigned int h,unsigned int v){ h ^= v + 0x9e3779b9u + (h<<6)+(h>>2); return h; }
static void clear5r(Axis6W5ReplayAgg* a){ for(int i=0;i<4;++i){ a->checkpoint[i]=0u; a->shadow[i]=0u; a->seen_mask[i]=0u; a->value[i]=0; } }
static void absorb5r(Axis6W5ReplayAgg* a,const Axis6W5ReplayRow* r){ unsigned int lane=r->lane%4u; if(r->checkpoint<a->checkpoint[lane]) return; if(r->checkpoint>a->checkpoint[lane]){ a->checkpoint[lane]=r->checkpoint; a->shadow[lane]=r->shadow; a->seen_mask[lane]=1u<<(r->token&31u); a->value[lane]=r->delta; return;} if(r->shadow<a->shadow[lane]) return; if(r->shadow>a->shadow[lane]){ a->shadow[lane]=r->shadow; a->seen_mask[lane]=1u<<(r->token&31u); a->value[lane]=r->delta; return;} { unsigned int bit=1u<<(r->token&31u); if(a->seen_mask[lane]&bit) return; a->seen_mask[lane]|=bit; } a->value[lane]+=r->delta; }
static unsigned int sig5r(const Axis6W5ReplayAgg* a){ unsigned int h=2166136261u; for(unsigned int lane=0;lane<4u;++lane){ h=mix5r(h,lane+1u); h=mix5r(h,a->checkpoint[lane]); h=mix5r(h,a->shadow[lane]); h=mix5r(h,a->seen_mask[lane]); h=mix5r(h,(unsigned int)(a->value[lane]&0xffff)); } return h; }
static void batch5r(Axis6W5ReplayAgg* a,const Axis6W5ReplayRow* rows,unsigned int count){ for(unsigned int i=0;i<count;++i) absorb5r(a,&rows[i]); }
int main(void){ const Axis6W5ReplayRow canonical[]={{0u,4u,2u,11u,5},{0u,4u,2u,17u,-1},{1u,5u,3u,13u,4},{1u,5u,3u,19u,2},{2u,6u,4u,23u,7},{2u,6u,4u,29u,-3},{3u,4u,5u,31u,6},{3u,4u,5u,5u,1}}; const Axis6W5ReplayRow replay_a[]={{0u,2u,1u,3u,1},{0u,4u,2u,11u,5},{1u,3u,2u,7u,2},{2u,6u,4u,23u,7},{1u,5u,3u,13u,4},{0u,4u,2u,11u,5},{3u,4u,5u,31u,6},{2u,6u,4u,29u,-3},{1u,5u,3u,19u,2},{3u,4u,5u,31u,6},{0u,4u,2u,17u,-1},{3u,4u,5u,5u,1}}; const Axis6W5ReplayRow replay_b[]={{3u,1u,2u,9u,4},{3u,4u,5u,5u,1},{1u,5u,3u,19u,2},{0u,4u,2u,17u,-1},{2u,6u,4u,23u,7},{1u,5u,3u,13u,4},{0u,4u,2u,11u,5},{3u,4u,5u,31u,6},{2u,6u,4u,29u,-3},{0u,4u,2u,17u,-1},{1u,5u,3u,19u,2},{3u,4u,5u,5u,1}}; Axis6W5ReplayAgg d,a,b; clear5r(&d); batch5r(&d,canonical,sizeof(canonical)/sizeof(canonical[0])); clear5r(&a); batch5r(&a,replay_a,sizeof(replay_a)/sizeof(replay_a[0])); clear5r(&b); batch5r(&b,replay_b,sizeof(replay_b)/sizeof(replay_b[0])); unsigned int sd=sig5r(&d), sa=sig5r(&a), sb=sig5r(&b); printf("%u %u %u %u\n", sd, sa, sb, (sd==sa && sd==sb)?1u:0u); return 0; }
